	@Test
	void usesTheLoadSchedulerForAllIndependentRecordSorters() throws Exception {
		long memoryBudgetBytes = 8L * 1024 * 1024;
		LmdbStoreConfig config = new LmdbStoreConfig("spoc");
		Path workspace = Files.createDirectory(temporaryDirectory.resolve("value-store"));
		var valueFactory = SimpleValueFactory.getInstance();
		CanonicalStagedInput staged;
		try (CanonicalStatementStager stager = new CanonicalStatementStager(workspace, config, 4, 8,
				memoryBudgetBytes, BulkCompression.NONE)) {
			stager.writeStatement(valueFactory.createStatement(valueFactory.createIRI("urn:subject"),
					valueFactory.createIRI("urn:predicate"), valueFactory.createIRI("urn:object")));
			staged = stager.stagedInput();
		}
		ValueDependencyBuckets dependencies = ValueDependencyCollector.collect(staged, workspace, 4, 8, config,
				BulkCompression.NONE, () -> false);
		PartitionValueDictionary dictionary = PartitionValueDictionaryBuilder.build(staged, dependencies, workspace,
				4, memoryBudgetBytes, 8, config, BulkCompression.NONE, () -> false);
		ResolvedValueRecords values = ResolvedValueRecords.build(dictionary, workspace, 8, memoryBudgetBytes, config,
				BulkCompression.NONE, () -> false);

		try (BulkTaskScheduler scheduler = new BulkTaskScheduler(2, memoryBudgetBytes, 8)) {
			Path resolvedWorkspace = Files.createDirectory(temporaryDirectory.resolve("resolved-value-chunks"));
			PartitionConcurrencyController controller = new PartitionConcurrencyController(System::nanoTime);
			controller.beginStage("resolved assigned-value components", 2, 2, 8);
			controller.setPhase(PartitionConcurrencyController.Phase.PRODUCING);
			ResolvedValueRecords scheduledValues = ResolvedValueRecords.build(dictionary, resolvedWorkspace, 8,
					memoryBudgetBytes, config, BulkCompression.NONE, () -> false, scheduler, controller);
			controller.finishStage();
			assertThat(scheduledValues.records()).isEqualTo(values.records());
			assertThat(scheduledValues.dependencyRecords()).isEqualTo(values.dependencyRecords());
			assertThat(readResolvedValues(scheduledValues)).isEqualTo(readResolvedValues(values));

			ValueStoreBulkRecords.Output output = ValueStoreBulkRecords.build(values, workspace, memoryBudgetBytes, 8,
					BulkCompression.NONE, () -> false, scheduler);

			assertThat(output.mainRecords().records()).isPositive();
			assertThat(output.referenceCounts().records()).isPositive();
			assertThat(scheduler.peakReservedMemoryBytes()).isPositive();
			assertThat(scheduler.peakReservedMemoryBytes()).isLessThanOrEqualTo(memoryBudgetBytes);
			assertThat(scheduler.peakReservedFileDescriptors()).isLessThanOrEqualTo(8);
		}
	}

