	@Test
	void dictionaryReaderAndOutputShareTheActiveResourceEnvelope() throws Exception {
		long memoryBudgetBytes = 2L * 1024 * 1024;
		int maxOpenFiles = 8;
		LmdbStoreConfig config = new LmdbStoreConfig("spoc");
		Path workspace = Files.createDirectory(temporaryDirectory.resolve("dictionary-reader-envelope"));
		var valueFactory = SimpleValueFactory.getInstance();
		CanonicalStagedInput staged;
		try (CanonicalStatementStager stager = new CanonicalStatementStager(workspace, config, 4, maxOpenFiles,
				memoryBudgetBytes, BulkCompression.NONE)) {
			stager.writeStatement(valueFactory.createStatement(valueFactory.createIRI("urn:subject"),
					valueFactory.createIRI("urn:predicate"), valueFactory.createIRI("urn:object")));
			staged = stager.stagedInput();
		}
		ValueDependencyBuckets dependencies = ValueDependencyCollector.collect(staged, workspace, 4, maxOpenFiles,
				config, BulkCompression.NONE, () -> false);
		PartitionValueDictionary dictionary = PartitionValueDictionaryBuilder.build(staged, dependencies, workspace, 4,
				memoryBudgetBytes, maxOpenFiles, config, BulkCompression.NONE, () -> false);

		try (BulkTaskScheduler scheduler = new BulkTaskScheduler(2, memoryBudgetBytes, maxOpenFiles)) {
			Path outputPath = workspace.resolve("dictionary-reader-output.bin");
			AtomicBoolean sawOverlappingHandles = new AtomicBoolean();
			dictionary.forEachEntry(entry -> {
				if (sawOverlappingHandles.get()) {
					return;
				}
				try (DataOutputStream output = BulkLz4.appendOutput(outputPath,
						BulkCompression.NONE.codecFor(BulkArtifact.VALUE_COMPONENT_BUCKETS), scheduler)) {
					output.writeLong(entry.id());
					sawOverlappingHandles.set(scheduler.openFileHandles() == 2);
				}
			}, scheduler);

			assertThat(sawOverlappingHandles)
					.as("dictionary input and component bucket output handles must overlap under one lease")
					.isTrue();
			assertThat(scheduler.peakOpenFileHandles()).isEqualTo(2);
			assertThat(scheduler.peakReservedFileDescriptors()).isLessThanOrEqualTo(maxOpenFiles);
			assertThat(scheduler.peakReservedMemoryBytes()).isGreaterThanOrEqualTo(64L * 1024L);
			assertThat(scheduler.peakReservedMemoryBytes()).isLessThanOrEqualTo(memoryBudgetBytes);
			assertThat(scheduler.reservedMemoryBytes()).isZero();
			assertThat(scheduler.openFileHandles()).isZero();
		}
	}

	@Test
	void overlapsValueSpillsWithBothResolvedValueReaders() throws Exception {
		long memoryBudgetBytes = 2L * 1024 * 1024;
		int maxOpenFiles = 16;
		LmdbStoreConfig config = new LmdbStoreConfig("spoc");
		Path workspace = Files.createDirectory(temporaryDirectory.resolve("value-spill-overlap"));
		var valueFactory = SimpleValueFactory.getInstance();
		CanonicalStagedInput staged;
		try (CanonicalStatementStager stager = new CanonicalStatementStager(workspace, config, 4, maxOpenFiles,
				memoryBudgetBytes, BulkCompression.NONE)) {
			for (int i = 0; i < 10_000; i++) {
				stager.writeStatement(valueFactory.createStatement(valueFactory.createIRI("urn:subject"),
						valueFactory.createIRI("urn:predicate"),
						valueFactory.createLiteral("value-" + i + "-" + "x".repeat(512))));
			}
			staged = stager.stagedInput();
		}
		ValueDependencyBuckets dependencies = ValueDependencyCollector.collect(staged, workspace, 4, maxOpenFiles,
				config, BulkCompression.NONE, () -> false);
		PartitionValueDictionary dictionary = PartitionValueDictionaryBuilder.build(staged, dependencies, workspace, 4,
				memoryBudgetBytes, maxOpenFiles, config, BulkCompression.NONE, () -> false);
		ResolvedValueRecords values = ResolvedValueRecords.build(dictionary, workspace, maxOpenFiles,
				memoryBudgetBytes, config, BulkCompression.NONE, () -> false);
		assertThat(values.readerFileDescriptorEstimate())
				.as("fixture must keep both assigned-value inputs open during conversion")
				.isEqualTo(2);
		Path serialWorkspace = Files.createDirectory(temporaryDirectory.resolve("value-spill-overlap-serial"));
		ValueStoreBulkRecords.Output serial = ValueStoreBulkRecords.build(values, serialWorkspace, memoryBudgetBytes,
				maxOpenFiles, BulkCompression.NONE, () -> false);

		AtomicBoolean workerSpillOverlappedReaders = new AtomicBoolean();
		AtomicInteger overlapHandles = new AtomicInteger(-1);
		CountDownLatch spillStarted = new CountDownLatch(1);
		try (BulkTaskScheduler scheduler = new BulkTaskScheduler(2, memoryBudgetBytes, maxOpenFiles)) {
			Path outputWorkspace = Files.createDirectory(temporaryDirectory.resolve("value-spill-overlap-output"));
			ValueStoreBulkRecords.Output output = ValueStoreBulkRecords.build(values, outputWorkspace,
					memoryBudgetBytes,
					maxOpenFiles, BulkCompression.NONE,
					() -> false, scheduler, () -> {
						int openHandles = scheduler.openFileHandles();
						if (scheduler.isWorkerThread() && overlapHandles.compareAndSet(-1, openHandles)) {
							workerSpillOverlappedReaders.set(openHandles >= 3);
							spillStarted.countDown();
						}
					}, () -> {
						try {
							assertThat(spillStarted.await(10, TimeUnit.SECONDS))
									.as("an asynchronous spill starts before the resolved-value readers close")
									.isTrue();
						} catch (InterruptedException e) {
							Thread.currentThread().interrupt();
							throw new AssertionError("interrupted while waiting for the asynchronous spill", e);
						}
					});

			assertThat(readRecords(output.mainRecords())).isEqualTo(readRecords(serial.mainRecords()));
			assertThat(readRecords(output.referenceCounts())).isEqualTo(readRecords(serial.referenceCounts()));
			assertThat(readTuples(output.tripleTerms())).isEqualTo(readTuples(serial.tripleTerms()));
			assertThat(readTuples(output.valueHashes())).isEqualTo(readTuples(serial.valueHashes()));

			assertThat(workerSpillOverlappedReaders)
					.as("the spill output overlaps both resolved-value input handles; observed %d open handles",
							overlapHandles.get())
					.isTrue();
			assertThat(overlapHandles).hasValue(3);
			assertThat(scheduler.peakReservedMemoryBytes()).isLessThanOrEqualTo(memoryBudgetBytes);
			assertThat(scheduler.reservedMemoryBytes()).isZero();
			assertThat(scheduler.openFileHandles()).isZero();
		}
	}

