	private static List<String> readRecords(ExternalByteKeySorter.SortedRecordFile file) throws Exception {
		List<String> records = new ArrayList<>();
		file.forEach(
				(key, value) -> records.add(HexFormat.of().formatHex(key) + ":" + HexFormat.of().formatHex(value)));
		return records;
	}

	private static List<String> readTuples(ExternalLongTupleSorter.SortedTupleFile file) throws Exception {
		List<String> records = new ArrayList<>();
		file.forEach(tuple -> records.add(Arrays.toString(tuple)));
		return records;
	}

	private static List<String> readResolvedValues(ResolvedValueRecords values) throws Exception {
		List<String> records = new ArrayList<>();
		values.forEach((sequence, id, roles, key, dependencyIds) -> records.add(sequence + ":" + id + ":" + roles
				+ ":" + Arrays.toString(key) + ":" + Arrays.toString(dependencyIds)), () -> false);
		return records;
	}
